/* ── Real-time polling notifications ─────────────────────────────────────── */
function useOrderNotifications(onNewOrder) {
  const lastPollRef = React.useRef(null);
  useEffect(() => {
    const token = localStorage.getItem('nb_admin_token');
    if (!token) return;
    const authH = { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` };
    const poll = async () => {
      try {
        const params = lastPollRef.current ? `?since=${encodeURIComponent(lastPollRef.current)}` : '';
        const res    = await fetch(`/api/admin/notifications/pending${params}`, { headers: authH });
        if (res.status === 401) {
            // Session expired — redirect to login (interval clears on unmount)
            window.location.href = '/admin';
            return;
        }
        if (!res.ok) return;
        const data = await res.json();
        if (data.alerts && data.alerts.length > 0) {
          lastPollRef.current = new Date().toISOString();
          data.alerts.forEach(alert => onNewOrder(alert));
          try {
            const ctx = new (window.AudioContext || window.webkitAudioContext)();
            [660, 880, 1100].forEach((freq, i) => {
              const osc  = ctx.createOscillator();
              const gain = ctx.createGain();
              osc.connect(gain); gain.connect(ctx.destination);
              osc.frequency.value = freq; osc.type = 'sine';
              gain.gain.setValueAtTime(0.25, ctx.currentTime + i * 0.18);
              gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + i * 0.18 + 0.15);
              osc.start(ctx.currentTime + i * 0.18);
              osc.stop(ctx.currentTime + i * 0.18 + 0.15);
            });
          } catch(_) {}
        }
      } catch(_) {}
    };
    poll();
    const iv = setInterval(poll, 5000);
    return () => clearInterval(iv);
  }, [onNewOrder]);
}

/* ── Alert Banner ─────────────────────────────────────────────────────────── */
function OrderAlertBanner({ alerts, onDismiss, onViewOrders }) {
  if (alerts.length === 0) return null;
  const latest = alerts[alerts.length - 1];
  return (
    <div style={{ position:'fixed', top:0, left:200, right:0, zIndex:99999, background:'linear-gradient(90deg,#dc2626,#b91c1c)', color:'#fff', padding:'0 24px', display:'flex', alignItems:'center', justifyContent:'space-between', fontFamily:"'DM Sans',sans-serif", boxShadow:'0 4px 24px rgba(220,38,38,.5)', animation:'nbAlertSlide .25s ease' }}>
      <style>{`@keyframes nbAlertSlide{from{transform:translateY(-100%)}to{transform:translateY(0)}} @keyframes nbPulse{0%,100%{opacity:1}50%{opacity:.6}} .nb-pulse{animation:nbPulse 1s ease infinite}`}</style>
      <div style={{ display:'flex', alignItems:'center', gap:16, padding:'12px 0' }}>
        <span className="nb-pulse" style={{ fontSize:24 }}>🚨</span>
        <div>
          <div style={{ fontSize:14, fontWeight:700 }}>NEW SQ-OFF — <span style={{ background:'rgba(255,255,255,.2)', borderRadius:5, padding:'2px 10px', marginLeft:4 }}>{latest.symbol}</span> · <span style={{ fontSize:12, opacity:.85 }}>{latest.exchange}/{latest.segment}</span></div>
          <div style={{ fontSize:12, opacity:.85, marginTop:3, display:'flex', gap:14 }}>
            <span>UCC: <strong>{latest.ucc}</strong></span>
            <span style={{ color:latest.side==='SELL'?'#fca5a5':'#86efac' }}>{latest.side} {latest.quantity}</span>
            <span>{new Date(latest.timestamp).toLocaleTimeString('en-IN', {hour:'2-digit',minute:'2-digit',second:'2-digit'})}</span>
            {alerts.length > 1 && <span style={{ background:'rgba(255,255,255,.25)', borderRadius:99, padding:'1px 9px', fontSize:11 }}>+{alerts.length-1} more</span>}
          </div>
        </div>
      </div>
      <div style={{ display:'flex', gap:10, padding:'12px 0', flexShrink:0 }}>
        <button onClick={onViewOrders} style={{ background:'#fff', color:'#dc2626', border:'none', borderRadius:7, padding:'8px 18px', fontSize:13, fontWeight:700, cursor:'pointer' }}>⚡ Process Order</button>
        <button onClick={onDismiss} style={{ background:'transparent', color:'rgba(255,255,255,.8)', border:'1px solid rgba(255,255,255,.35)', borderRadius:7, padding:'8px 14px', fontSize:12, cursor:'pointer' }}>Dismiss</button>
      </div>
    </div>
  );
}

