/* ── Segment Control Panel ────────────────────────────────────────────────── */
function SegmentControl({ segments, onToggle, onAlert, toggling, communicating, T }) {
  const [activeEx, setActiveEx] = useState('NSE');
  const [termSel, setTermSel] = useState({});
  const S = getAdminStyles(T);
  const enabled = segments.filter(s => s.is_enabled).length;

  return (
    <div>
      {/* Stat cards */}
      <div style={{ display:'grid', gridTemplateColumns:'repeat(3,1fr)', gap:12, marginBottom:20 }}>
        {[
          { label:'Total Segments',  value:segments.length,        color:T.brand },
          { label:'Active',          value:enabled,                color:T.ok    },
          { label:'Inactive',        value:segments.length-enabled, color:T.err  },
        ].map(c => (
          <div key={c.label} style={{ ...S.statCard }}>
            <div style={{ ...S.statLabel }}>{c.label}</div>
            <div style={{ ...S.statNum(c.color) }}>{c.value}</div>
          </div>
        ))}
      </div>

      {/* Platform status bar */}
      <div style={{ background:T.warnBg, border:`0.5px solid ${T.warn}`, borderRadius:8, padding:'10px 16px', marginBottom:16, display:'flex', alignItems:'center', gap:10 }}>
        <div style={{ width:6, height:6, borderRadius:'50%', background:T.warn, flexShrink:0 }}/>
        <span style={{ fontSize:12, color:T.warnTx }}>Platform monitoring active · {segments.filter(s=>s.is_enabled).length} of {segments.length} segments enabled</span>
        <button onClick={()=>window.location.reload()} style={{ marginLeft:'auto', ...S.btnGhost, fontSize:11, padding:'4px 12px' }}>↻ Refresh</button>
      </div>

      {/* Segment panel */}
      <div style={{ ...S.card }}>
        {/* Exchange tabs */}
        <div style={{ display:'flex', borderBottom:`0.5px solid ${T.bdr}` }}>
          {['NSE','BSE','MCX'].map(ex => {
            const exSegs = segments.filter(s => s.exchange===ex);
            const actCnt = exSegs.filter(s => s.is_enabled).length;
            const ec = EX_COLORS[ex];
            return (
              <div key={ex} onClick={()=>setActiveEx(ex)}
                style={{ padding:'10px 24px', cursor:'pointer', fontSize:13, fontWeight:500, color:activeEx===ex?T.brand:T.tx2, borderBottom:`2px solid ${activeEx===ex?T.brand:'transparent'}`, background:activeEx===ex?T.brandL:'transparent', display:'flex', alignItems:'center', gap:8, transition:'all .15s' }}>
                <span style={{ ...S.badge(ec.bg, ec.col, ec.bdr) }}>{ex}</span>
                {actCnt>0 && <span style={{ ...S.pill(T.okBg, T.ok) }}>{actCnt} active</span>}
              </div>
            );
          })}
        </div>
        {/* Table header */}
        <div style={{ display:'grid', gridTemplateColumns:'2fr 90px 120px 150px 140px 200px', padding:'9px 20px', background:T.surf2, borderBottom:`0.5px solid ${T.bdr}` }}>
          {['Segment','Type','Status','Terminal','Last Updated','Actions'].map(h=>(
            <div key={h} style={{ fontSize:10, color:T.tx2, fontWeight:600, textTransform:'uppercase', letterSpacing:.4 }}>{h}</div>
          ))}
        </div>
        {/* Segment rows */}
        {SEGMENTS[activeEx].map((seg, i) => {
          const data = segments.find(s=>s.exchange===activeEx&&s.segment===seg.segment)||{};
          const key  = `${activeEx}-${seg.segment}`;
          const on   = data.is_enabled;
          const upd  = data.enabled_at ? new Date(data.enabled_at).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}) : '—';
          const ec   = EX_COLORS[activeEx];
          const selectedTerminal = termSel[key] !== undefined ? termSel[key] : (data.terminal || '');
          return (
            <div key={key} style={{ display:'grid', gridTemplateColumns:'2fr 90px 120px 150px 140px 200px', padding:'13px 20px', alignItems:'center', borderBottom: i<SEGMENTS[activeEx].length-1?`0.5px solid ${T.bdr}`:'none', background:on?T.brandL:T.surf }}>
              <div>
                <div style={{ fontSize:13, fontWeight:500, color:T.tx }}>{seg.name}</div>
                <div style={{ fontSize:10, color:T.tx3, marginTop:2 }}>{seg.code}</div>
              </div>
              <div><span style={{ ...S.badge(ec.bg,ec.col,ec.bdr) }}>{seg.segment}</span></div>
              <div style={{ display:'flex', alignItems:'center', gap:6 }}>
                <div style={{ width:7, height:7, borderRadius:'50%', background:on?'#16a34a':'#d1d5db' }}/>
                <span style={{ fontSize:12, fontWeight:500, color:on?T.ok:T.tx3 }}>{on?'Active':'Inactive'}</span>
              </div>
              <div>
                <select
                  value={selectedTerminal}
                  disabled={on}
                  onChange={e => setTermSel(s => ({ ...s, [key]: e.target.value }))}
                  style={{ fontSize:11, padding:'4px 6px', borderRadius:5, border:`0.5px solid ${T.bdr}`, background:on?T.surf2:T.surf, color:on?T.tx3:T.tx, fontFamily:"'DM Sans',sans-serif", cursor:on?'not-allowed':'pointer', width:'100%' }}>
                  <option value="">Select…</option>
                  <option value="INHOUSE">Inhouse</option>
                  <option value="BOW">BoW</option>
                </select>
              </div>
              <div style={{ fontSize:11, color:T.tx2 }}>{upd}</div>
              <div style={{ display:'flex', gap:8 }}>
                <button onClick={()=>onAlert(activeEx,seg.segment)} disabled={communicating[key]}
                  style={{ ...S.btnGhost, fontSize:11, padding:'5px 12px', opacity:communicating[key]?.6:1 }}>
                  {communicating[key]?'Sending...':'📢 Alert Clients'}
                </button>
                <button onClick={()=>onToggle(activeEx,seg.segment,on,selectedTerminal)} disabled={toggling[key] || (!on && !selectedTerminal)}
                  title={(!on && !selectedTerminal) ? 'Select a terminal first' : undefined}
                  style={{ padding:'5px 14px', borderRadius:5, border:`0.5px solid ${on?T.err:T.ok}`, background:on?T.errBg:T.okBg, color:on?T.err:T.ok, fontSize:11, fontWeight:500, cursor:(toggling[key]||(!on&&!selectedTerminal))?'not-allowed':'pointer', fontFamily:"'DM Sans',sans-serif", opacity:(toggling[key]||(!on&&!selectedTerminal))?.5:1 }}>
                  {toggling[key]?'...':on?'Disable':'Enable'}
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

/* ══ MAIN AdminDashboard ══════════════════════════════════════════════════════ */
export default function AdminDashboard({ admin, onLogout }) {
  const [activeNav,     setActiveNav]     = useState('segments');
  const [segments,      setSegments]      = useState([]);
  const [loading,       setLoading]       = useState(true);
  const [toggling,      setToggling]      = useState({});
  const [communicating, setCommunicating] = useState({});
  const [toast,         setToast]         = useState(null);
  const [orderAlerts,   setOrderAlerts]   = useState([]);
  const [themeKey,      setThemeKey]      = useState(() => localStorage.getItem('nb_admin_theme')||'light');

  const T = ADMIN_THEMES[themeKey];

  // Inject CSS vars + DM Sans whenever theme changes
  useEffect(() => {
    injectAdminThemeVars(T);
    localStorage.setItem('nb_admin_theme', themeKey);
    document.body.style.background = T.bg;
    document.body.style.fontFamily = "'DM Sans',-apple-system,sans-serif";

    // Inject global CSS overrides for sub-pages dark/light theme
    let el = document.getElementById('nb-admin-theme-style');
    if (!el) { el = document.createElement('style'); el.id = 'nb-admin-theme-style'; document.head.appendChild(el); }
    el.textContent = `
      .nb-admin-content, .nb-admin-content * { font-family: 'DM Sans',-apple-system,sans-serif !important; }
      .nb-admin-content { color: ${T.tx} !important; }
      .nb-admin-content > div { background: transparent !important; }
      .nb-admin-content [style*="background: '#fff'"],
      .nb-admin-content [style*='background: "#fff"'] { background: ${T.surf} !important; }
      .nb-admin-content input, .nb-admin-content select {
        background: ${T.surf2} !important;
        color: ${T.tx} !important;
        border-color: ${T.bdr2} !important;
      }
    `;
  }, [T, themeKey]);

  const toggleTheme = () => setThemeKey(k => k==='light'?'dark':'light');

  const showToast = (msg, type='success') => { setToast({msg,type}); setTimeout(()=>setToast(null),4000); };

  const handleNewOrder = useCallback((orderData) => {
    setOrderAlerts(prev => [...prev, orderData]);
  }, []);

  useOrderNotifications(handleNewOrder);

  const handleDismissAlerts = () => {
    const ids = orderAlerts.map(a=>a.orderId);
    setOrderAlerts([]);
    const token = localStorage.getItem('nb_admin_token');
    if (token && ids.length>0) fetch('/api/admin/notifications/seen',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({order_ids:ids})}).catch(()=>{});
  };

  const handleViewOrders = () => { setActiveNav('orders'); handleDismissAlerts(); };

  const loadSegments = async () => {
    try { const res=await (await fetch('/api/admin/control/segments',{headers:{'Authorization':`Bearer ${localStorage.getItem('nb_admin_token')}`}})).json(); setSegments(res.segments||[]); }
    catch { showToast('Failed to load segments.','error'); }
    finally { setLoading(false); }
  };

  useEffect(() => { loadSegments(); }, []);

  const handleToggle = async (exchange, segment, on, terminal) => {
    const key = `${exchange}-${segment}`;
    if (!on && !terminal) {
      showToast('Select a terminal (Inhouse or BoW) before enabling this segment.', 'error');
      return;
    }
    setToggling(t=>({...t,[key]:true}));
    try {
      const res = await (await fetch('/api/admin/control/segments/toggle',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('nb_admin_token')}`},body:JSON.stringify({exchange,segment,enable:!on,notes:'',terminal: !on ? terminal : undefined})})).json();
      if (res.error) { showToast(res.error,'error'); return; }
      showToast(`${exchange} ${segment} ${!on?'enabled':'disabled'} successfully`);
      loadSegments();
    } catch(err) { showToast(err.message||'Failed.','error'); }
    finally { setToggling(t=>({...t,[key]:false})); }
  };

  const handleAlert = async (exchange, segment) => {
    const key = `${exchange}-${segment}`;
    if (!window.confirm(`Send Email + WhatsApp to all clients with open ${exchange} ${segment} positions?`)) return;
    setCommunicating(c=>({...c,[key]:true}));
    try {
      const res = await (await fetch('/api/admin/control/communicate',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${localStorage.getItem('nb_admin_token')}`},body:JSON.stringify({exchange,segment,send_email:true,send_whatsapp:true})})).json();
      showToast(`Sent to ${res.total_clients} clients`);
    } catch(err) { showToast('Communication failed.','error'); }
    finally { setCommunicating(c=>({...c,[key]:false})); }
  };

  const navTitles = {
    segments: { title:'Segment Control',       sub:'Manage exchange segments and client communications' },
    orders:   { title:'Square-Off Orders',      sub:'View and manage client sq-off requests'            },
    alerts:   { title:'Client Alerts',          sub:'Bulk communication history'                        },
    bfupload: { title:'B/F Position Upload',    sub:'Upload daily NSE FO and MCX carried-forward files' },
    reports:  { title:'Order Reports',          sub:'Download exchange-wise reports'                     },
    dealer:   { title:'Dealer Access',          sub:'SSO and dealer order management'                    },
    logs:     { title:'Audit Logs',             sub:'System activity and admin actions'                  },
    syslogs:  { title:'System Logs',            sub:'Complete audit trail for compliance'                },
    users:    { title:'User Management',        sub:'Admin and sub-user access control'                  },
    clients:  { title:'Client Upload',          sub:'Bulk upload clients via CSV file'                   },
    syncmon:  { title:'Sync Monitor',           sub:'DropCopy sync status and logs'                      },
  };
  const current = navTitles[activeNav]||navTitles.segments;
  const S = getAdminStyles(T);

  return (
    <AdminThemeContext.Provider value={{ themeKey, T, toggleTheme }}>
      <div style={{ display:'flex', minHeight:'100vh', background:T.bg, fontFamily:"'DM Sans',-apple-system,sans-serif" }}>

        {/* Order alert banner */}
        <OrderAlertBanner alerts={orderAlerts} onDismiss={handleDismissAlerts} onViewOrders={handleViewOrders}/>

        {/* Toast */}
        {toast && <div style={{...S.toast(toast.type)}}>{toast.msg}</div>}

        {/* Sidebar */}
        <Sidebar activeNav={activeNav} onNav={setActiveNav} admin={admin} pendingCount={orderAlerts.length} T={T}
          onLogout={()=>{ localStorage.removeItem('nb_admin_token'); localStorage.removeItem('nb_admin'); onLogout(); }}/>

        {/* Main */}
        <div style={{ marginLeft:210, flex:1, display:'flex', flexDirection:'column', minHeight:'100vh' }}>
          <Topbar title={current.title} subtitle={current.sub} admin={admin} T={T} themeKey={themeKey} toggleTheme={toggleTheme}/>

          <div className="nb-admin-content" style={{ padding:'20px 24px', flex:1, background:T.bg }}>
            {activeNav==='segments' && (
              loading
                ? <div style={{...S.empty}}>Loading segments...</div>
                : <SegmentControl segments={segments} onToggle={handleToggle} onAlert={handleAlert} toggling={toggling} communicating={communicating} T={T}/>
            )}
            {/* Keep components mounted to avoid reload delay on tab switch */}
            <div style={{display: activeNav==='orders'  ?'block':'none'}}><SqOffOrders/></div>
            <div style={{display: activeNav==='alerts'  ?'block':'none'}}><ClientAlerts/></div>
            <div style={{display: activeNav==='bfupload'?'block':'none'}}><BFUpload/></div>
            <div style={{display: activeNav==='reports' ?'block':'none'}}><OrderReports/></div>
            <div style={{display: activeNav==='dealer'  ?'block':'none'}}><DealerAccessPanel/></div>
            <div style={{display: activeNav==='logs'    ?'block':'none'}}><AuditLogs/></div>
            <div style={{display: activeNav==='syslogs' ?'block':'none'}}><SystemLogsPanel/></div>
            <div style={{display: activeNav==='syncmon' ?'block':'none'}}><SyncMonitor/></div>
            <div style={{display: activeNav==='users'   ?'block':'none'}}><UserManagement/></div>
            <div style={{display: activeNav==='clients' ?'block':'none'}}><ClientUpload/></div>
          </div>

          <div style={{ textAlign:'center', padding:'12px', fontSize:10, color:T.tx3, borderTop:`0.5px solid ${T.bdr}` }}>
            Navia Markets Ltd · RMS Admin Terminal · {new Date().getFullYear()}
          </div>
        </div>
      </div>
    </AdminThemeContext.Provider>
  );
}